import React, { useState, useEffect } from "react";
import styled from "styled-components";
import { X } from "lucide-react";

const PopupOverlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
`;

const PopupContent = styled.div`
  background: #fff;
  padding: 20px;
  border-radius: 8px;
  width: 500px;
  height: 600px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  position: relative;
`;

const PopupInput = styled.input`
  padding: 8px;
  border: 1px solid #ddd;
  border-radius: 4px;
  width: 100%;
`;

const PopupTextarea = styled.textarea`
  padding: 10px;
  height: 500px;
  border: 1px solid #ddd;
  border-radius: 4px;
  resize: none;
`;

const PopupSelect = styled.select`
  padding: 8px;
  border: 1px solid #ddd;
  border-radius: 4px;
  width: 100%;
`;

const PopupButton = styled.button`
  padding: 10px;
  background: #2196f3;
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;

  &:hover {
    background: #1976d2;
  }
`;

const CloseIcon = styled.span`
  position: absolute;
  top: 10px;
  right: 10px;
  cursor: pointer;
  color: #555;
`;

const FlexContainer = styled.div`
  display: flex;
  gap: 10px;
`;

const ViewTaskPopup = ({ showPopup, setShowPopup, task, updateTask, quadrantNames }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editedTask, setEditedTask] = useState({});

  useEffect(() => {
    if (task) {
      setEditedTask({ ...task });
    }
  }, [task]);

  const handleUpdateTask = () => {
    if (!editedTask.title.trim()) return;
    updateTask(editedTask);
    setIsEditing(false);
  };

  const handleClose = (e) => {
    if (e.target === e.currentTarget) {
      setShowPopup(false);
    }
  };

  if (!showPopup) return null;

  return (
    <PopupOverlay onClick={handleClose}>
      <PopupContent key={task.id}>
        <CloseIcon onClick={() => setShowPopup(false)}>
          <X size={24} />
        </CloseIcon>
        <h3>{isEditing ? "Edit Task" : "View Task"}</h3>
        <PopupInput
          type="text"
          placeholder="Task Name"
          value={editedTask.title || ""}
          onChange={(e) => setEditedTask({ ...editedTask, title: e.target.value })}
          disabled={!isEditing}
        />
        <PopupTextarea
          placeholder="Task Description"
          value={editedTask.description || ""}
          maxLength={500}
          onChange={(e) => setEditedTask({ ...editedTask, description: e.target.value })}
          disabled={!isEditing}
        />
        <FlexContainer>
          <PopupInput
            type="date"
            value={editedTask.dueDate || ""}
            onChange={(e) => setEditedTask({ ...editedTask, dueDate: e.target.value })}
            disabled={!isEditing}
          />
          <PopupSelect
            value={editedTask.quadrant || ""}
            onChange={(e) => setEditedTask({ ...editedTask, quadrant: e.target.value })}
            disabled={!isEditing}
          >
            <option value="" disabled>Select Quadrant</option>
            {quadrantNames.map((quadrant) => (
              <option key={quadrant.id} value={quadrant.id}>{quadrant.priority_name}</option>
            ))}
          </PopupSelect>
        </FlexContainer>
        <PopupButton onClick={() => setIsEditing(!isEditing)}>
          {isEditing ? "Cancel" : "Edit Task"}
        </PopupButton>
        {isEditing && <PopupButton onClick={handleUpdateTask}>Update Task</PopupButton>}
      </PopupContent>
    </PopupOverlay>
  );
};

export default ViewTaskPopup;