import React, { useState, useEffect } from "react";
import styled from "styled-components";
import { X } from "lucide-react";

const PopupOverlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
`;

const PopupContent = styled.div`
  background: #fff;
  padding: 20px;
  border-radius: 8px;
  width: 500px;
  height: 600px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  position: relative;
`;

const PopupInput = styled.input`
  padding: 8px;
  border: 1px solid #ddd;
  border-radius: 4px;
  width: 100%;
`;

const PopupTextarea = styled.textarea`
  padding: 10px;
  height: 500px;
  border: 1px solid #ddd;
  border-radius: 4px;
  resize: none;
`;

const PopupSelect = styled.select`
  padding: 8px;
  border: 1px solid #ddd;
  border-radius: 4px;
  width: 100%;
`;

const PopupButton = styled.button`
  padding: 10px;
  background: #2196f3;
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;

  &:hover {
    background: #1976d2;
  }
`;

const CloseIcon = styled.span`
  position: absolute;
  top: 10px;
  right: 10px;
  cursor: pointer;
  color: #555;
`;

const FlexContainer = styled.div`
  display: flex;
  gap: 10px;
`;

const TaskPopup = ({ showPopup, setShowPopup, addTask, quadrantNames }) => {
  const [newTask, setNewTask] = useState({ title: "", description: "", dueDate: "", quadrant: 1 });

  useEffect(() => {
    if (showPopup) {
      const currentDate = new Date().toISOString().split("T")[0];
      setNewTask((prevTask) => ({ ...prevTask, dueDate: currentDate }));
    }
  }, [showPopup]);

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === "Enter") {
        handleAddTask();
      }
    };

    if (showPopup) {
      window.addEventListener("keydown", handleKeyDown);
    } else {
      window.removeEventListener("keydown", handleKeyDown);
    }

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [showPopup, newTask]);

  const handleAddTask = () => {
    if (!newTask.title.trim()) return;
    addTask(newTask);
    setShowPopup(false);
    setNewTask({ title: "", description: "", dueDate: "", quadrant: 1 });
  };

  const handleClose = (e) => {
    if (e.target === e.currentTarget) {
      setShowPopup(false);
    }
  };

  if (!showPopup) return null;

  return (
    <PopupOverlay onClick={handleClose}>
      <PopupContent>
        <CloseIcon onClick={() => setShowPopup(false)}>
          <X size={24} />
        </CloseIcon>
        <h3>Add Task</h3>
        <PopupInput
          type="text"
          placeholder="Task Name"
          value={newTask.title}
          onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
        />
        <PopupTextarea
          placeholder="Task Description"
          value={newTask.description}
          maxLength={500}
          onChange={(e) => setNewTask({ ...newTask, description: e.target.value })}
        />
        <FlexContainer>
        <PopupInput
          type="date"
          value={newTask.dueDate}
          onChange={(e) => setNewTask({ ...newTask, dueDate: e.target.value })}
        />
        <PopupSelect
          value={newTask.quadrant}
          onChange={(e) => setNewTask({ ...newTask, quadrant: parseInt(e.target.value) })}
        >
          {quadrantNames.map((quadrant) => (
            <option key={quadrant.id} value={quadrant.id}>{quadrant.priority_name}</option>
          ))}
        </PopupSelect>
        </FlexContainer>
        <PopupButton onClick={handleAddTask}>Add Task</PopupButton>
      </PopupContent>
    </PopupOverlay>
  );
};

export default TaskPopup;